final _timeout = const Duration(seconds: 8);

  // Max size for cached responses in the device memory.
  final _cacheMemorySize = 2 * 1024 * 1024;

  /// The location where api key is stored.
  final apiKeyPath = 'assets/keys/api_keys.json';

  /// Header with api key.
  late final Map<String, String> _headers;

  Future<ApiService> create() async {
    await _setRequestHeaders();
    _setPlatformClient();
    return this;
  }

  void _setPlatformClient() {
    try {
      if (Platform.isIOS) {
        final config =
            cupertino.URLSessionConfiguration.ephemeralSessionConfiguration()
              ..cache = cupertino.URLCache.withCapacity(
                  memoryCapacity: _cacheMemorySize);
        _client = cupertino.CupertinoClient.fromSessionConfiguration(config);
      } else {
        final engine = cronet.CronetEngine.build(
          cacheMode: cronet.CacheMode.memory,
          cacheMaxSize: _cacheMemorySize,
        );
        _client = cronet.CronetClient.fromCronetEngine(engine);
      }
    } catch (error) {
      _logsService.log(
        trigger: runtimeType,
        systemLog: error,
        customLog:
            'None of platform specific client is supported. The default IOClient will be used.',
      );
      _client = IOClient();
    }
  }

  Future<void> _setRequestHeaders() async {
    try {
      // Get api key.
      final apiKeyRawData =
          await rootBundle.loadString(apiKeyPath).timeout(_timeout);
      final apiKeyData = jsonDecode(apiKeyRawData);

      // Get user-agent for debugging in backend.
      final appInfo = await PackageInfo.fromPlatform();
      String userAgent =
          '${Flavor.instance.appName} ${Flavor.instance.configs.partnerName}';
      userAgent += ' ${appInfo.version}';
      userAgent += ' ${Flavor.instance.stage}';

      _headers = {
        'User-Agent': userAgent,
        'X-API-KEY': apiKeyData['api_key'],
      };
